def has_path_sum(root, targetSum):
    if not root:
        return False

    stack = [(root, root.val)]

    while stack:
        node, total = stack.pop()
        if not node.left and not node.right: # if leaf node
            if total == targetSum:
                return True
        if node.left:
            stack.append((node.left, total + node.left.val))
        if node.right:
            stack.append((node.right, total + node.right.val))

    return False
