``` c++
#include <iostream>
#include <string>
using namespace std;

int countStringOccurrences(string source, string search)
{
    int count = 0;
    int pos = source.find(search, 0); // find the first occurrence of the search string
    while (pos != string::npos)
    {
        count++; // increment the count
        pos = source.find(search, pos + 1); // find the next occurrence starting from the previous position + 1
    }
    return count;
}
``` 

